  const rows=JSON.parse(fs.readFileSync(r+'.json','utf8'));
  if(!Array.isArray(rows)) throw new Error(r+' not array');
  const ids=rows.map(x=>x.id);
  const complete=rows.every(x=>Number.isInteger(x.units)&&Number.isInteger(x.weight));
  const contiguous=ids.length>0&&new Set(ids).size===ids.length&&Math.min(...ids)===1&&Math.max(...ids)===ids.length;
  const count=rows.length;
  const units=rows.reduce((a,x)=>a+x.units,0);
  const weighted=rows.reduce((a,x)=>a+x.units*x.weight,0);
  total+=count; gu+=units; gw+=weighted;
  const a=ans.regions[r];
  const matchInsp=insp[r].count===count&&insp[r].units===units&&insp[r].weighted===weighted;
  const matchAns=a&&a.count===count&&a.units===units&&a.weighted===weighted;
  if(!matchInsp||!matchAns||!complete||!contiguous) ok=false;
  console.log(r,'count='+count,'units='+units,'weighted='+weighted,'integers='+complete,'idsContiguous='+contiguous,'inspectorMatch='+matchInsp,'answerMatch='+matchAns);
}
const keys=Object.keys(ans).sort().join(',');
